// Ekstrakcja danych z wiadomości Gmail
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Pobierz dane wiadomości
  const messageId = data.id || data.messageId;
  const threadId = data.threadId;
  const subject = data.subject || data.Subject || '';

  // POPRAWKA: Bezpieczne wyciąganie danych z pola 'from'
  let fromText = '';
  if (typeof data.from === 'string') {
    fromText = data.from;
  } else if (data.from && data.from.text) {
    fromText = data.from.text;
  } else if (data.from && data.from.value && data.from.value[0]) {
    // Fallback - zbuduj string z obiektu
    const fromObj = data.from.value[0];
    fromText = fromObj.name 
      ? `"${fromObj.name}" <${fromObj.address}>`
      : fromObj.address;
  } else if (data.From) {
    fromText = data.From;
  }

  // POPRAWKA: Bezpieczne wyciąganie danych z pola 'to'
  let toText = '';
  if (typeof data.to === 'string') {
    toText = data.to;
  } else if (data.to && data.to.text) {
    toText = data.to.text;
  } else if (data.to && data.to.value && data.to.value[0]) {
    toText = data.to.value[0].address;
  } else if (data.To) {
    toText = data.To;
  }

  // Ekstrakcja adresu email nadawcy
  let senderEmail = '';
  let senderName = '';

  // Sprawdź czy from ma strukturę obiektu z value
  if (data.from && data.from.value && data.from.value[0]) {
    senderEmail = data.from.value[0].address;
    senderName = data.from.value[0].name || senderEmail.split('@')[0];
  } else {
    // Fallback - parsowanie z tekstu
    const senderEmailMatch = fromText.match(/<(.+?)>/);
    if (senderEmailMatch) {
      senderEmail = senderEmailMatch[1];
    } else if (fromText.includes('@')) {
      senderEmail = fromText.trim();
    }

    // Ekstrakcja imienia z nadawcy
    const senderNameMatch = fromText.match(/^["']?(.+?)["']?\s*</);
    senderName = senderNameMatch ? senderNameMatch[1].trim() : senderEmail.split('@')[0];
  }

  // Jeśli nie udało się wydobyć emaila, pomiń ten item
  if (!senderEmail) {
    console.log('Skipping item - no sender email found');
    continue;
  }

  // Pobierz treść emaila
  let emailBody = data.text || data.plainText || data.textPlain || '';

  // Jeśli nie ma plain text, spróbuj HTML
  if (!emailBody && (data.html || data.textHtml)) {
    const htmlContent = data.html || data.textHtml;
    // Podstawowe usunięcie tagów HTML
    emailBody = htmlContent
      .replace(/<style[^>]*>.*?<\/style>/gi, '')
      .replace(/<script[^>]*>.*?<\/script>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&quot;/g, '"')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&nacute;/g, 'ń')
      .replace(/&zdot;/g, 'ż')
      .replace(/&oacute;/g, 'ó')
      .replace(/\s+/g, ' ')
      .trim();
  }

  // Jeśli nadal nie ma treści, spróbuj snippet
  if (!emailBody && data.snippet) {
    emailBody = data.snippet;
  }

// Usuń cytowane poprzednie wiadomości, ale zachowaj odpowiedzi powyżej i poniżej cytatu
const lines = emailBody.split('\n');
const cleanLines = [];
let skipQuoted = false;

for (const line of lines) {
  const trimmed = line.trim();

  // Wykryj początek sekcji cytowanej (różne języki i formaty)
  if (
    trimmed.match(/^>/) ||
    trimmed.match(/^On .* wrote:/i) ||
    trimmed.match(/^W dniu .* napisał/i) ||
    trimmed.match(/^Dnia .* napisał/i) ||
    trimmed.includes('Original Message') ||
    trimmed.includes('Wiadomość oryginalna')
  ) {
    skipQuoted = true;
    continue;
  }

  // Jeśli mamy pustą linię po cytacie, kończymy sekcję cytowaną
  if (skipQuoted && trimmed === '') {
    skipQuoted = false;
    continue;
  }

  if (!skipQuoted) {
    cleanLines.push(line);
  }
}

let cleanedBody = cleanLines.join('\n').trim();

// Jeśli po czyszczeniu nadal mało tekstu, fallback do oryginału
if (!cleanedBody || cleanedBody.length < 5) {
  cleanedBody = emailBody.trim();
}


  // Jeśli po czyszczeniu nie ma treści, pomiń
  if (!cleanedBody || cleanedBody.length < 5) {
    console.log('Skipping item - no content after cleaning');
    continue;
  }

  // Generuj sessionId (unikalny dla każdego emaila klienta)
  const sessionId = `gmail_${senderEmail.replace(/[^a-z0-9]/gi, '_')}`;

  // Pobierz datę z właściwego pola
  const receivedDate = data.date || new Date().toISOString();

  results.push({
    json: {
      messageId,
      threadId,
      subject,
      from: fromText,
      to: toText,
      senderEmail,
      senderName,
      emailBody: cleanedBody,
      originalEmailBody: emailBody,
      sessionId,
      receivedAt: receivedDate
    }
  });
}

return results;

// Formatowanie odpowiedzi AI do wysłania przez Gmail
const items = $input.all();
const results = [];

for (const item of items) {
  const agentOutput = item.json.output || item.json.text || '';
  const context = $('⚙️ Przygotowanie kontekstu').first().json;
  const senderEmail = context.senderEmail;
  const senderName = context.senderName;
  const messageId = context.messageId;
  const threadId = context.threadId;
  const subject = context.subject;

  // Funkcja do konwersji Markdown do HTML
  function markdownToHtml(text) {
    let html = text;

    // Konwersja bold **text** -> <strong>text</strong>
    html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

    // Konwersja italic *text* -> <em>text</em>
    html = html.replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g, '<em>$1</em>');

    // Konwersja nagłówków
    html = html.replace(/^### (.+)$/gm, '<h3 style="color: #2c5f2d; margin-top: 15px;">$1</h3>');
    html = html.replace(/^## (.+)$/gm, '<h2 style="color: #2c5f2d; margin-top: 20px;">$1</h2>');
    html = html.replace(/^# (.+)$/gm, '<h1 style="color: #2c5f2d; border-bottom: 3px solid #97bc62; padding-bottom: 10px;">$1</h1>');

    return html;
  }

  // Sprawdź czy odpowiedź już jest w pełnym HTML
  const isFullHtml = agentOutput.toLowerCase().includes('<!doctype') || 
                     agentOutput.toLowerCase().includes('<html');

  let formattedMessage = '';

  if (isFullHtml) {
    // Jeśli już jest pełny HTML, użyj bezpośrednio
    formattedMessage = agentOutput;
  } else {
    // Konwertuj markdown/tekst na HTML
    let processedText = markdownToHtml(agentOutput);

    // Podziel na akapity
    const paragraphs = processedText.split(/\n\n+/).map(p => {
      p = p.trim();
      if (!p) return '';

      // Jeśli to już jest tag HTML, zostaw go
      if (p.startsWith('<h1') || p.startsWith('<h2') || p.startsWith('<h3')) {
        return p;
      }

      // Obsługa list
      if (p.includes('\n- ') || p.includes('\n• ') || p.match(/^[-•]/)) {
        const items = p.split('\n').filter(line => {
          const trimmed = line.trim();
          return trimmed.startsWith('-') || trimmed.startsWith('•') || trimmed.match(/^\d+\./);
        });

        if (items.length > 0) {
          const listItems = items.map(item => {
            const text = item.replace(/^\s*[-•]\s*/, '').replace(/^\d+\.\s*/, '');
            return `<li style="margin: 8px 0;">${text}</li>`;
          }).join('');
          return `<ul style="padding-left: 20px; margin: 10px 0;">${listItems}</ul>`;
        }
      }

      // Konwersja pojedynczych newline na <br>
      p = p.replace(/\n/g, '<br>');

      // Zwykły akapit
      return `<p style="line-height: 1.6; margin: 10px 0;">${p}</p>`;
    }).filter(p => p).join('\n');

    formattedMessage = `<!DOCTYPE html>
<html lang="pl">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Odpowiedź</title>
</head>
<body style="font-family: Arial, sans-serif; color: #333; max-width: 700px; margin: 0 auto; padding: 20px; line-height: 1.6;">
${paragraphs}
</body>
</html>`;
  }

  results.push({
    json: {
      to: senderEmail,
      subject: subject.startsWith('Re:') ? subject : `Re: ${subject}`,
      message: formattedMessage,
      emailType: 'html',
      messageId: messageId,
      threadId: threadId,
      senderName: senderName,
      _debug_originalOutput: agentOutput.substring(0, 200)
    }
  });
}

return results;
